return ['domain'=>'bulk-editor','plural-forms'=>'nplurals=2; plural=n > 1;','language'=>'fr_FR','project-id-version'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional 2.1.3','pot-creation-date'=>'2026-11-20T14:15:27+00:00','po-revision-date'=>'2026-11-20 15:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WOLF - WordPress Posts Bulk Editor and Manager Professional'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional','https://bulk-editor.pro/'=>'https://bulk-editor.pro/','Tools for managing and bulk edit posts, pages and all custom types data in the reliable and flexible way! Be professionals with managing data of your site!'=>'Outils de gestion et de modification en masse des articles, pages et de tous les types de contenu personnalisés, de façon fiable et flexible. Gérez les données de votre site comme un professionnel !','realmag777'=>'realmag777','https://pluginus.net/'=>'https://pluginus.net/','no rounding'=>'pas d’arrondi','forbidden'=>'interdit','Default'=>'Par défaut','Checkboxes for the posts selection. Use SHIFT button on your keyboard to select multiple rows.'=>'Cases à cocher pour la sélection des articles. Maintenez la touche MAJ enfoncée pour sélectionner plusieurs lignes.','Thumbnail'=>'Miniature','Title'=>'Titre','Content'=>'Contenu','Excerpt'=>'Extrait','Slug'=>'Identifiant (slug)','Status'=>'Statut','Comment status'=>'Statut des commentaires','Can users comment post or not.'=>'Les utilisateurs peuvent-ils commenter l’article ou non.','Open'=>'Ouverts','Closed'=>'Fermés','Ping status'=>'Statut des pings','A ping is a [this site has new content] notification that invites search engine bots to visit your blog.'=>'Un ping est une notification « ce site a du nouveau contenu » qui invite les robots des moteurs de recherche à visiter votre blog.','Send trackbacks to'=>'Envoyer des rétroliens à','Separate multiple URLs with spaces. Ping status should be open! Remove 2 links separated by space, save. After opening you will not see links as they had been pinged! No sense for roll back, its sending is instant. Trackbacks are a way to notify legacy blog systems that you’ve linked to them. If you link other WordPress sites, they’ll be notified automatically using pingbacks, no other action necessary. Do not use these fields for something else. They are parsed many times in core code (69 matches for to_ping); their format is fixed.'=>'Séparez plusieurs URL par des espaces. Le statut des pings doit être ouvert ! Supprimez 2 liens séparés par un espace, puis enregistrez. Après ouverture, vous ne verrez plus les liens, car ils ont déjà été pingés ! Inutile de revenir en arrière : l’envoi est instantané. Les rétroliens permettent de notifier les anciens systèmes de blog que vous avez lié vers eux. Si vous liez d’autres sites WordPress, ils sont notifiés automatiquement par pingbacks, sans autre action. N’utilisez pas ces champs à d’autres fins. Ils sont analysés à de nombreux endroits du code du cœur (69 occurrences de to_ping) ; leur format est fixe.','Post password'=>'Mot de passe de l’article','Password for private posts'=>'Mot de passe pour les articles privés','Menu order'=>'Ordre du menu','Custom ordering position.'=>'Position de tri personnalisée.','Author'=>'Auteur','Date Published'=>'Date de publication','Date Published GMT'=>'Date de publication GMT','Date modified'=>'Date de modification','Date modified GMT'=>'Date de modification GMT','Post parent'=>'Article parent','Post type'=>'Type de contenu','Post mime type'=>'Type MIME','Not in bulk edit as there is no built-uploader here, so no sense change mime type. Filtering only! The function is designed specifically for attached records.'=>'Absent de la modification en masse : il n’y a pas de téléversement intégré ici, donc modifier le type MIME n’a aucun sens. Filtrage uniquement ! La fonction est conçue spécialement pour les contenus attachés.','Sticky'=>'Épinglé','Stick this post to the front page'=>'Épingler cet article sur la page d’accueil','Yes'=>'Oui','No'=>'Non','Default posts count per page'=>'Nombre d’articles par page par défaut','How many rows shows per page in tab Posts Editor. Max possible value is 100!'=>'Nombre de lignes affichées par page dans l’onglet Éditeur d’articles. La valeur maximale est 100 !','Default sort by'=>'Tri par défaut sur','Select column by which posts sorting is going after plugin page loaded'=>'Sélectionnez la colonne selon laquelle les articles sont triés après le chargement de la page du plugin','Default sort'=>'Ordre de tri par défaut','Select sort direction for Default sort'=>'Sélectionnez le sens du tri pour le tri par défaut','Show button in admin bar'=>'Afficher le bouton dans la barre d’admin','Show Bulk Editor button in admin bar for quick access to the Posts Editor'=>'Afficher le bouton Bulk Editor dans la barre d’admin pour accéder rapidement à l’Éditeur d’articles','Show thumbnail preview'=>'Afficher l’aperçu de la miniature','Show bigger thumbnail preview on mouse over'=>'Afficher un aperçu agrandi de la miniature au survol de la souris','Load beauty switchers'=>'Charger les interrupteurs stylisés','Load beauty switchers instead of checkboxes in the Posts Editor.'=>'Charger des interrupteurs stylisés à la place des cases à cocher dans l’Éditeur d’articles.','Use gutenberg'=>'Utiliser Gutenberg','Allows to edit content with the gutenberg editor if its enabled for the selected post type'=>'Permet de modifier le contenu avec l’éditeur Gutenberg s’il est activé pour le type de contenu sélectionné','Add fields to the quick search'=>'Ajouter des champs à la recherche rapide','Adds more fields to quick search fields drop-down on the tools panel. Works only for text fields. Syntax: post_name:Post slug,post_content:Content'=>'Ajoute des champs à la liste déroulante de recherche rapide du panneau d’outils. Ne fonctionne que pour les champs texte. Syntaxe : post_name:Identifiant,post_content:Contenu','Override meta checkbox'=>'Remplacer la case à cocher méta','By default, the checkbox works with 1 and 0. If you need to redefine these values for example to "yes" or "true". Syntax: meta_key1:yes,meta_key2:true'=>'Par défaut, la case à cocher utilise 1 et 0. Si vous devez redéfinir ces valeurs, par exemple en « yes » ou « true ». Syntaxe : meta_key1:yes,meta_key2:true','Bulk Edit'=>'Modification en masse','Will be edited next:'=>'Seront modifiés ensuite :','Sure? Delete [%s]?'=>'Confirmer ? Supprimer [%s] ?','Bulk deleting'=>'Suppression en masse','[%s](s) deleted!'=>'[%s](s) supprimé(s) !','Bulk editing'=>'Modification en masse','[%s](s) edited! Table redrawing ...'=>'[%s](s) modifié(s) ! Rechargement du tableau…','[%s](s) edited!'=>'[%s](s) modifié(s) !','ATTENTION: Bulk operation is going!'=>'ATTENTION : une opération en masse est en cours !','binded editing'=>'modification liée','In FREE version of the plugin you can change only next fields: %s'=>'Dans la version GRATUITE du plugin, vous ne pouvez modifier que les champs suivants : %s','In this mode to the all selected [%1$s](s) will be set the value of a [%2$s] field which been edited'=>'Dans ce mode, la valeur du champ [%2$s] qui a été modifié sera appliquée à tous les [%1$s](s) sélectionnés','Select post type you want to manage'=>'Sélectionnez le type de contenu à gérer','title'=>'titre','content'=>'contenu','excerpt'=>'extrait','slug'=>'identifiant (slug)','password'=>'mot de passe','send trackbacks to'=>'envoyer des rétroliens à','post status'=>'statut de l’article','post type'=>'type de contenu','comment status'=>'statut des commentaires','ping status'=>'statut des pings','sticky posts'=>'articles épinglés','increase by value'=>'augmenter de la valeur','decrease by value'=>'diminuer de la valeur','increase by %'=>'augmenter de %','decrease by %'=>'diminuer de %','set new'=>'définir une nouvelle valeur','delete'=>'supprimer','post parent'=>'article parent','menu order'=>'ordre du menu','Bulk editing will be applied to: %s'=>'La modification en masse sera appliquée à : %s','all the [%s] on the site'=>'tous les [%s] du site','text'=>'texte','numeric'=>'numérique','statuses and types'=>'statuts et types','Do Bulk Edit'=>'Lancer la modification','terminate bulk operation'=>'arrêter l’opération en masse','Delete [%s]!'=>'Supprimer [%s] !','Notes'=>'Notes','In red containers wrapped fields which are not possible modify in bulk in FREE version of the plugin!'=>'Les champs encadrés en rouge ne peuvent pas être modifiés en masse dans la version GRATUITE du plugin !','In the case of an aborted bulk-operation you can roll back changes in the tab History'=>'En cas d’opération en masse interrompue, vous pouvez annuler les modifications dans l’onglet Historique','Time by time (one time per week for example) - make the backup of your site database. For example by %s'=>'De temps en temps (une fois par semaine par exemple), sauvegardez la base de données de votre site. Par exemple avec %s','this plugin'=>'ce plugin','Documentation'=>'Documentation','select it to use'=>'sélectionner pour utiliser','variable'=>'variable','TITLE'=>'TITRE','MENU ORDER'=>'ORDRE DU MENU','append'=>'ajouter à la fin','prepend'=>'ajouter au début','new'=>'nouveau','replace'=>'remplacer','same case'=>'casse identique','ignore case'=>'ignorer la casse','replace to text'=>'remplacer par le texte','Select how to round float values fractions in the numeric fields. Works for numeric meta fields. Read more %s.'=>'Choisissez comment arrondir les décimales des valeurs à virgule dans les champs numériques. Fonctionne pour les champs méta numériques. En savoir plus %s.','here'=>'ici','Selected num fields'=>'Champs numériques sélectionnés','You can select numeric field then make math operation with another numeric field using [+ - * /] value'=>'Vous pouvez sélectionner un champ numérique puis effectuer une opération mathématique avec un autre champ numérique à l’aide de [+ - * /] valeur','Random number'=>'Nombre aléatoire','Decimal'=>'Décimal','From:'=>'De :','To:'=>'À :','You can create random numbers for test filling fields or for SEO tasks'=>'Vous pouvez créer des nombres aléatoires pour remplir des champs de test ou pour des tâches SEO','taxonomies'=>'taxonomies','remove'=>'retirer','Set: %s'=>'Définir : %s','other'=>'autre','select thumbnail'=>'sélectionner la miniature','enter operation value'=>'saisir la valeur de l’opération','Export'=>'Exporter','Should the export be started?'=>'Lancer l’export ?','Exporting'=>'Export en cours','Exported'=>'Exporté','ATTENTION: Export operation is going!'=>'ATTENTION : une opération d’export est en cours !','Export will be applied to: %s'=>'L’export sera appliqué à : %s','Note: you can change columns set and then set their order in the tab Settings, then save it as columns profile which in future will help you with exporting the [%s] data format quickly without necessary each time set columns order and their set!'=>'Remarque : vous pouvez modifier l’ensemble des colonnes et leur ordre dans l’onglet Réglages, puis l’enregistrer comme profil de colonnes. Cela vous permettra d’exporter rapidement les données au format [%s] sans avoir à redéfinir à chaque fois les colonnes et leur ordre !','Export to CSV'=>'Exporter en CSV','Export to XML'=>'Exporter en XML','Export to Excel'=>'Exporter vers Excel','download'=>'télécharger','download XML'=>'télécharger le XML','cancel export'=>'annuler l’export','Current export functionality is just for simple operations and data share, if you need something complex find and use especial plugin for Export WordPress data!'=>'La fonction d’export actuelle sert uniquement aux opérations simples et au partage de données. Pour des besoins complexes, utilisez un plugin spécialisé dans l’export des données WordPress !','Select CSV data delimiter.'=>'Sélectionnez le séparateur de données CSV.','Filters'=>'Filtres','Filtering'=>'Filtrage','Filtered! Table redrawing ...'=>'Filtré ! Rechargement du tableau…','LIKE'=>'CONTIENT','EXACT'=>'EXACT','NOT'=>'NON','BEGIN'=>'DÉBUT','END'=>'FIN','ID'=>'ID','quick search by ...'=>'recherche rapide par…','Filter'=>'Filtrer','Reset'=>'Réinitialiser','Empty'=>'Vide','ID(s). Use comma or/and minus for range'=>'ID. Utilisez une virgule et/ou un tiret pour une plage','[%s] title ...'=>'Titre [%s]…','[%s] content ...'=>'Contenu [%s]…','[%s] excerpt ...'=>'Extrait [%s]…','[%s] slug ...'=>'Identifiant (slug) [%s]…','[%s] password ...'=>'Mot de passe [%s]…','Menu order from'=>'Ordre du menu à partir de','Menu order to'=>'Ordre du menu jusqu’à','Post parent from'=>'Article parent à partir de','Post parent to'=>'Article parent jusqu’à','[%s] status'=>'Statut [%s]','Sticky posts'=>'Articles épinglés','By author'=>'Par auteur','Not empty'=>'Non vide','%s from'=>'%s à partir de','%s to'=>'%s jusqu’à','test'=>'test','Filters profiles'=>'Profils de filtres','Profiles'=>'Profils','Here you can load previously saved filters profile. After pressing on the load button, Posts Editor data reloading will start immediately!'=>'Vous pouvez charger ici un profil de filtres enregistré précédemment. Après un clic sur le bouton de chargement, les données de l’Éditeur d’articles seront rechargées immédiatement !','Select filter profile to load'=>'Sélectionnez le profil de filtres à charger','load'=>'charger','New Filter Profile'=>'Nouveau profil de filtres','Here you can type any title and save current filters set. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Saisissez ici un titre pour enregistrer l’ensemble de filtres actuel. Saisissez un titre puis cliquez sur le bouton Enregistrer OU appuyez sur la touche Entrée de votre clavier !','You can save filter profile only when you applying filters to the posts.'=>'Vous ne pouvez enregistrer un profil de filtres que lorsque des filtres sont appliqués aux articles.','Save'=>'Enregistrer','Close'=>'Fermer','History'=>'Historique','Reverting'=>'Annulation en cours','Reverted!'=>'Annulé !','Wait please while data reverting is going!'=>'Veuillez patienter pendant l’annulation des données !','History clearing ...'=>'Effacement de l’historique…','History is cleared!'=>'L’historique est effacé !','ATTENTION: History operation is going!'=>'ATTENTION : une opération sur l’historique est en cours !','This clears the history of all users for this post type, including the AI agent rows. It cannot be undone. Continue?'=>'Cette action efface l’historique de tous les utilisateurs pour ce type de contenu, y compris les lignes de l’agent IA. Elle est irréversible. Continuer ?','This clears your own history for this post type. It cannot be undone. Continue?'=>'Cette action efface votre propre historique pour ce type de contenu. Elle est irréversible. Continuer ?','WOLF cannot create the database table! Make sure that your mysql user has the CREATE privilege! Do it manually using your host panel phpmyadmin!'=>'WOLF ne peut pas créer la table de la base de données ! Vérifiez que votre utilisateur MySQL dispose du privilège CREATE ! Faites-le manuellement depuis le panneau de votre hébergeur avec phpMyAdmin !','AI agent'=>'Agent IA','user #%d'=>'utilisateur n° %d','%s (AI agent)'=>'%s (agent IA)','This history entry is not yours. Only an administrator can roll back or delete the changes of other users.'=>'Cette entrée de l’historique n’est pas la vôtre. Seul un administrateur peut annuler ou supprimer les modifications des autres utilisateurs.','Bulk operation'=>'Opération en masse','state: %s'=>'état : %s','value been: %s'=>'valeur précédente : %s','posts bulked: %s'=>'articles modifiés : %s','columns: %s'=>'colonnes : %s','revert'=>'annuler','History is empty!'=>'L’historique est vide !','Works for edit-operations and not work with delete-operations!'=>'Fonctionne pour les opérations de modification, mais pas pour les suppressions !','In FREE version of the plugin it is possible to roll back 2 last operations.'=>'Dans la version GRATUITE du plugin, il est possible d’annuler les 2 dernières opérations.','Per page:'=>'Par page :','ALL'=>'TOUT','Clear the History'=>'Effacer l’historique','all'=>'tout','solo operations'=>'opérations individuelles','bulk operations'=>'opérations en masse','by Author'=>'par auteur','by date from'=>'à partir du','clear'=>'effacer','by date to'=>'jusqu’au','by fields'=>'par champs','Prev'=>'Préc.','of'=>'sur','Next'=>'Suiv.','Help'=>'Aide','The plugin has next info: %1$s, %2$s, %3$s. Also if you have troubles you can %4$s!'=>'Le plugin propose les informations suivantes : %1$s, %2$s, %3$s. En cas de difficulté, vous pouvez également %4$s !','documentation'=>'documentation','translations'=>'traductions','FAQ'=>'FAQ','ask for support here'=>'demander de l’aide ici','Current version of the plugin is FREE. See the difference between FREE and PREMIUM versions %s'=>'La version actuelle du plugin est GRATUITE. Consultez la différence entre les versions GRATUITE et PREMIUM %s','Some little hints'=>'Petits conseils','Can I connect an AI assistant (Claude, ChatGPT, Cursor and others) to WOLF and edit posts by chatting with it? Yes - %s'=>'Puis-je connecter un assistant IA (Claude, ChatGPT, Cursor et autres) à WOLF et modifier des articles en discutant avec lui ? Oui - %s','here is how to connect it'=>'voici comment le connecter','If to click on an empty space of the black wp-admin bar, it will get you back to the top of the page'=>'Si vous cliquez sur un espace vide de la barre noire de wp-admin, vous revenez en haut de la page','How to set the same value for some posts on the same time - %s'=>'Comment définir la même valeur pour plusieurs articles à la fois - %s','How to use - %s'=>'Comment l’utiliser - %s','meta field Gallery'=>'champ méta Galerie','Search by posts slugs, which are in non-latin symbols does not work because in the data base they are keeps in the encoded format!'=>'La recherche par identifiants (slugs) d’articles en caractères non latins ne fonctionne pas, car ils sont stockés encodés dans la base de données !','Click ID of the post in the Posts Editor to see it on the site front.'=>'Cliquez sur l’ID de l’article dans l’Éditeur d’articles pour le voir sur le site.','Use Enter keyboard button in the Posts Editor for moving to the next posts row cell with saving of changes while edit textinputs. Use arrow Up or arrow Down keyboard buttons in the Posts Editor for moving to the next/previous posts row without saving of changes.'=>'Dans l’Éditeur d’articles, utilisez la touche Entrée pour passer à la cellule suivante de la ligne avec enregistrement des modifications lors de la saisie dans un champ texte. Utilisez les flèches Haut et Bas pour passer à la ligne suivante ou précédente sans enregistrer les modifications.','To select range of posts using checkboxes - select first post, press SHIFT key on your PC keyboard and click last post.'=>'Pour sélectionner une plage d’articles avec les cases à cocher, sélectionnez le premier article, maintenez la touche MAJ enfoncée et cliquez sur le dernier.','If you like WOLF %s about what you liked and what you want to see in future versions of the plugin'=>'Si WOLF vous plaît, %s ce que vous avez aimé et ce que vous aimeriez voir dans les prochaines versions du plugin','write us feedback please'=>'écrivez-nous pour nous dire','If you have an idea you can %s'=>'Si vous avez une idée, vous pouvez %s','share it with us here'=>'la partager avec nous ici','Requirements'=>'Prérequis','Recommended min RAM'=>'RAM minimale recommandée','Minimal PHP version is'=>'Version minimale de PHP :','Recommended PHP version'=>'Version de PHP recommandée','Type part of a name, login or e-mail'=>'Saisissez une partie du nom, de l’identifiant ou de l’e-mail','No matching user who can work with WOLF'=>'Aucun utilisateur correspondant pouvant utiliser WOLF','Working...'=>'Traitement…','Disconnect'=>'Déconnecter','Issue a new key? The old key stops working at once and the assistant using it is disconnected.'=>'Émettre une nouvelle clé ? L’ancienne clé cesse de fonctionner immédiatement et l’assistant qui l’utilise est déconnecté.','Something went wrong. Reload the page and try again.'=>'Une erreur s’est produite. Rechargez la page et réessayez.','cannot connect: this user can no longer work with WOLF'=>'connexion impossible : cet utilisateur ne peut plus utiliser WOLF','no key yet - it is issued when the user opens his settings'=>'pas encore de clé - elle est émise lorsque l’utilisateur ouvre ses réglages','MCP access for users'=>'Accès MCP pour les utilisateurs','Save the settings after changing the list. A user taken off the list loses his key and his connection at once.'=>'Enregistrez les réglages après avoir modifié la liste. Un utilisateur retiré de la liste perd immédiatement sa clé et sa connexion.','Users picked here get a personal MCP key in their own settings and connect an AI assistant under their own WordPress account: the assistant can do exactly what they can do by hand, with their role and field visibility, never more. Two-factor connection is always on for personal keys. Only users who can work with WOLF are offered. The site-wide key above is not affected and stays yours.'=>'Les utilisateurs choisis ici obtiennent une clé MCP personnelle dans leurs propres réglages et connectent un assistant IA sous leur propre compte WordPress : l’assistant peut faire exactement ce qu’ils peuvent faire manuellement, avec leur rôle et la visibilité de leurs champs, jamais plus. La connexion à deux facteurs est toujours activée pour les clés personnelles. Seuls les utilisateurs pouvant utiliser WOLF sont proposés. La clé globale du site ci-dessus n’est pas affectée et reste la vôtre.','Your MCP access'=>'Votre accès MCP','Address for the assistant:'=>'Adresse pour l’assistant :','Your personal key:'=>'Votre clé personnelle :','Regenerate key'=>'Régénérer la clé','Give the assistant the address and this key as a request header: Authorization, with the value "Bearer" followed by a space and the key. Two-factor connection is always on for a personal key: every session starts with a token the assistant shows you, which you confirm below.'=>'Donnez à l’assistant l’adresse et cette clé en en-tête de requête : Authorization, avec la valeur « Bearer » suivie d’une espace et de la clé. La connexion à deux facteurs est toujours activée pour une clé personnelle : chaque session commence par un jeton que l’assistant vous montre et que vous confirmez ci-dessous.','Confirm assistant connection - paste the token the assistant gave you:'=>'Confirmer la connexion de l’assistant - collez le jeton que l’assistant vous a donné :','Confirm connection'=>'Confirmer la connexion','The administrator gave you MCP access. An assistant connected with your key works as you: it can do what you can do by hand in this plugin, with your role and field visibility. Keep the key private; if it may have leaked, press Regenerate key - the old key and its connection stop working at once.'=>'L’administrateur vous a donné un accès MCP. Un assistant connecté avec votre clé agit en votre nom : il peut faire ce que vous pouvez faire manuellement dans ce plugin, avec votre rôle et la visibilité de vos champs. Gardez la clé privée ; si elle a pu fuiter, cliquez sur Régénérer la clé - l’ancienne clé et sa connexion cessent de fonctionner immédiatement.','You cannot work with WOLF on this site.'=>'Vous ne pouvez pas utiliser WOLF sur ce site.','Only an administrator can do this.'=>'Seul un administrateur peut faire cela.','You have no MCP access on this site. Ask the administrator to grant it.'=>'Vous n’avez pas d’accès MCP sur ce site. Demandez à l’administrateur de vous l’accorder.','No user given.'=>'Aucun utilisateur indiqué.','Disconnected.'=>'Déconnecté.','A new key is issued. The old one no longer works - update it in your assistant.'=>'Une nouvelle clé a été émise. L’ancienne ne fonctionne plus - mettez-la à jour dans votre assistant.','That is not a connection token. Copy the whole token the assistant gave you - four groups of eight characters separated by dashes.'=>'Ce n’est pas un jeton de connexion. Copiez le jeton complet donné par l’assistant - quatre groupes de huit caractères séparés par des tirets.','Connected. Go back to the assistant and tell it you have confirmed.'=>'Connecté. Retournez dans l’assistant et dites-lui que vous avez confirmé.','Not connected'=>'Non connecté','Connected, last activity %d min ago'=>'Connecté, dernière activité il y a %d min','Only an administrator can confirm a connection.'=>'Seul un administrateur peut confirmer une connexion.','Only an administrator can end a connection.'=>'Seul un administrateur peut mettre fin à une connexion.','No assistant is connected.'=>'Aucun assistant n’est connecté.','An assistant is connected since %1$s. If it stays idle, the connection ends at %2$s.'=>'Un assistant est connecté depuis %1$s. S’il reste inactif, la connexion prend fin à %2$s.','Recommended: turn on two-factor connection. Without it, anyone who gets hold of the MCP key - from a screenshot, a shared config or a stolen laptop - can work with your site. With it, every assistant session also needs a token that you confirm here yourself, and that expires after %s without use.'=>'Recommandé : activez la connexion à deux facteurs. Sans elle, quiconque obtient la clé MCP - via une capture d’écran, une configuration partagée ou un ordinateur volé - peut agir sur votre site. Avec elle, chaque session d’assistant exige aussi un jeton que vous confirmez vous-même ici, et qui expire après %s sans utilisation.','Enable the MCP server'=>'Activer le serveur MCP','The MCP server is on: assistants can connect at the address below.'=>'Le serveur MCP est activé : les assistants peuvent se connecter à l’adresse ci-dessous.','The MCP server is off and no assistant can connect. Choose Yes here: the key and the other MCP settings appear below, and Save switches the server on.'=>'Le serveur MCP est désactivé et aucun assistant ne peut se connecter. Choisissez Oui ici : la clé et les autres réglages MCP apparaissent ci-dessous, et Enregistrer active le serveur.','Off by default. The MCP server lets an AI assistant read and edit the posts of this site over a REST endpoint. While it is off, the endpoint is not registered at all and nothing can reach it. Turn it on only when you are about to connect an assistant, and turn it back off if you stop using one.'=>'Désactivé par défaut. Le serveur MCP permet à un assistant IA de lire et de modifier les articles de ce site via un point d’accès REST. Tant qu’il est désactivé, le point d’accès n’est pas enregistré du tout et rien ne peut l’atteindre. Activez-le uniquement lorsque vous êtes sur le point de connecter un assistant, et désactivez-le si vous cessez d’en utiliser un.','MCP secret key'=>'Clé secrète MCP','Not active: the MCP server is switched off above.'=>'Inactif : le serveur MCP est désactivé ci-dessus.','Adding it in claude.ai: its server check will say "Couldn\'t check the server" with 403. That is expected for a server that signs in with a key - press "Continue anyway" and add the header Authorization with the value "Bearer" followed by a space and the key.'=>'Lors de l’ajout dans claude.ai : la vérification du serveur affichera « Couldn\'t check the server » avec une erreur 403. C’est normal pour un serveur qui s’authentifie par clé - cliquez sur « Continue anyway » et ajoutez l’en-tête Authorization avec la valeur « Bearer » suivie d’une espace et de la clé.','How to connect an AI assistant'=>'Comment connecter un assistant IA','Lets an AI assistant work with the posts of this site through a chat: find them, change them in bulk, roll changes back. Give the assistant the address below and this key as a request header named Authorization, with the value "Bearer" followed by a space and the key. Some clients call it an API key header instead - X-WPBE-KEY works the same way. The key is never accepted in the address itself, because anything written into a URL ends up in server logs, browser history and every proxy along the way. Clear this field and press Save to issue a new key: the old one stops working at once and every connected assistant has to be reconnected.'=>'Permet à un assistant IA de travailler avec les articles de ce site par le chat : les trouver, les modifier en masse, annuler les modifications. Donnez à l’assistant l’adresse ci-dessous et cette clé en en-tête de requête nommé Authorization, avec la valeur « Bearer » suivie d’une espace et de la clé. Certains clients l’appellent plutôt en-tête de clé API - X-WPBE-KEY fonctionne de la même façon. La clé n’est jamais acceptée dans l’adresse elle-même, car tout ce qui est écrit dans une URL se retrouve dans les journaux du serveur, l’historique du navigateur et chaque proxy traversé. Videz ce champ et cliquez sur Enregistrer pour émettre une nouvelle clé : l’ancienne cesse de fonctionner immédiatement et chaque assistant connecté doit être reconnecté.','MCP two-factor connection'=>'Connexion MCP à deux facteurs','recommended'=>'recommandé','This does not switch the MCP server on - that is "Enable the MCP server" above. Two-factor connection takes effect once the server is on.'=>'Cela n’active pas le serveur MCP - c’est l’option « Activer le serveur MCP » ci-dessus. La connexion à deux facteurs prend effet une fois le serveur activé.','Off by default, recommended. With it on, the MCP key alone is not enough: every assistant session starts by showing you a token, you paste it below and confirm, and only then can the assistant work. The connection ends by itself after %s without activity, so a leaked key is useless without you. One assistant is connected at a time.'=>'Désactivé par défaut, recommandé. Une fois activé, la clé MCP seule ne suffit plus : chaque session d’assistant commence par vous montrer un jeton, vous le collez ci-dessous et le confirmez, et seulement alors l’assistant peut travailler. La connexion se termine d’elle-même après %s sans activité, de sorte qu’une clé divulguée est inutile sans vous. Un seul assistant est connecté à la fois.','Upload images'=>'Téléverser des images','Add images to your site'=>'Ajouter des images à votre site','The first one becomes the featured image of %s.'=>'La première devient l’image mise en avant de %s.','They go into the media library, ready to put on a post.'=>'Elles vont dans la médiathèque, prêtes à être ajoutées à un article.','Drop images here'=>'Déposez les images ici','or click to choose them'=>'ou cliquez pour les choisir','Meta Fields'=>'Champs méta','Meta key cannot be empty!'=>'La clé méta ne peut pas être vide !','Enter a post ID!'=>'Saisissez un ID d’article !','No meta keys found!'=>'Aucune clé méta trouvée !','New meta key'=>'Nouvelle clé méta','EXACT (=)'=>'EXACT (=)','NOT EXACT (!=)'=>'NON EXACT (!=)','NOT LIKE'=>'NE CONTIENT PAS','NOT Empty'=>'NON vide','In FREE version of the plugin it is possible manipulate with 2 meta fields.'=>'Dans la version GRATUITE du plugin, il est possible de manipuler 2 champs méta.','Add Custom key by hands'=>'Ajouter une clé personnalisée manuellement','Add'=>'Ajouter','Get meta keys from any post by its ID'=>'Récupérer les clés méta de n’importe quel article par son ID','enter post ID'=>'saisir l’ID de l’article','Get'=>'Récupérer','Meta quick search ...'=>'Recherche rapide de méta…','Save meta fields'=>'Enregistrer les champs méta','move'=>'déplacer','enter title'=>'saisir le titre','textinput'=>'champ texte','textarea'=>'zone de texte','checkbox'=>'case à cocher','calendar'=>'calendrier','array'=>'tableau','gallery'=>'galerie','string'=>'chaîne','number'=>'nombre','Hello, looks like you bought and installed premium version of WOLF - WordPress Posts Bulk Editor and Manager Professional, please deactivate free version before, then uninstall it. 2 versions of the same plugin cannot be activated on the same time!'=>'Bonjour, il semble que vous ayez acheté et installé la version premium de WOLF - WordPress Posts Bulk Editor and Manager Professional. Veuillez d’abord désactiver la version gratuite, puis la désinstaller. Deux versions du même plugin ne peuvent pas être activées en même temps !','If you not familiar with the plugin, firstly'=>'Si vous ne connaissez pas le plugin, commencez par','visit this page'=>'visiter cette page','please'=>'veuillez','WOLF Bulk Editor'=>'WOLF Bulk Editor','Posts Editor'=>'Éditeur d’articles','Search'=>'Rechercher','Failed'=>'Échec','Error'=>'Erreur','ignore'=>'ignorer','This is not deletable!'=>'Ceci ne peut pas être supprimé !','no items'=>'aucun élément','none'=>'aucun','no data'=>'aucune donnée','Loading'=>'Chargement','Loaded'=>'Chargé','Saved'=>'Enregistré','Saving'=>'Enregistrement','Apply'=>'Appliquer','Cancel'=>'Annuler','Canceled'=>'Annulé','Sure?'=>'Confirmer ?','Creating'=>'Création','Created!'=>'Créé !','Duplicating'=>'Duplication','Duplicated!'=>'Dupliqué !','Deleting'=>'Suppression','Deleted!'=>'Supprimé !','Reseting'=>'Réinitialisation','Reseted!'=>'Réinitialisé !','Upload image'=>'Téléverser une image','Upload file'=>'Téléverser un fichier','Fill up the data please!'=>'Veuillez remplir les données !','Enter how many time duplicate selected [%s](s)!'=>'Saisissez combien de fois dupliquer les [%s](s) sélectionnés !','Enter how many new [%s](s) to create!'=>'Saisissez combien de nouveaux [%s](s) créer !','Text search by title or SKU'=>'Recherche de texte par titre ou UGS','Show: Filters/Bulk Edit/Export'=>'Afficher : Filtres/Modification en masse/Export','Hide: Filters/Bulk Edit/Export'=>'Masquer : Filtres/Modification en masse/Export','Per page'=>'Par page','Select background color'=>'Sélectionner la couleur d’arrière-plan','Select text color'=>'Sélectionner la couleur du texte','No data available in the table'=>'Aucune donnée disponible dans le tableau','Showing _START_ to _END_ of _TOTAL_ entries'=>'Affichage de _START_ à _END_ sur _TOTAL_ entrées','Showing 0 to 0 of 0 entries'=>'Affichage de 0 à 0 sur 0 entrée','(filtered from _MAX_ total entries)'=>'(filtré à partir de _MAX_ entrées au total)','Loading...'=>'Chargement…','Processing...'=>'Traitement…','No matching records found'=>'Aucun enregistrement correspondant trouvé','First'=>'Premier','Last'=>'Dernier','Previous'=>'Précédent','the filtered [%s]. To remove filtering press reset button on the tools panel below'=>'les [%s] filtrés. Pour supprimer le filtrage, cliquez sur le bouton de réinitialisation du panneau d’outils ci-dessous','the selected [%s](s)'=>'les [%s](s) sélectionnés','You can reset selection of the [%s](s) by its reset button on the panel of the editor OR uncheck them manually!'=>'Vous pouvez réinitialiser la sélection des [%s](s) avec son bouton de réinitialisation sur le panneau de l’éditeur OU les décocher manuellement !','Maybe term(s) with such name(s) already exists!'=>'Un ou plusieurs termes portant ce(s) nom(s) existent peut-être déjà !','In FREE version of the plugin you can create one profile only!'=>'Dans la version GRATUITE du plugin, vous ne pouvez créer qu’un seul profil !','append sub item'=>'ajouter un sous-élément','This field is deactivated in FREE version for bulk edit!'=>'Ce champ est désactivé dans la version GRATUITE pour la modification en masse !','Posts checked'=>'Articles cochés','View the post on the site front'=>'Voir l’article sur le site public','Editing of the post on its page'=>'Modifier l’article sur sa page','Posts not found!'=>'Aucun article trouvé !','New %s'=>'Nouveau : %s','copy'=>'copie','see the post on the site'=>'voir l’article sur le site','Scheduled'=>'Planifié','Later'=>'Plus tard','Hi! Are you enjoying using WOLF – WordPress Posts Bulk Editor Professional?'=>'Bonjour ! Appréciez-vous WOLF – WordPress Posts Bulk Editor Professional ?','Yes, I love it'=>'Oui, j’adore','Not really...'=>'Pas vraiment…','That\'s awesome! Could you please do us a BIG favor and give it a 5-star rating on %s to help us spread the word and boost our motivation?'=>'Super ! Pourriez-vous nous rendre un GRAND service en lui donnant 5 étoiles sur %s pour nous aider à nous faire connaître et à nous motiver ?','Okay, you deserve it'=>'D’accord, vous le méritez','Nope, maybe later'=>'Non, peut-être plus tard','I already did'=>'C’est déjà fait','We are sorry to hear you aren\'t enjoying WOLF. We would love a chance to improve it. Could you take a minute and let us know what we can do better?'=>'Nous sommes désolés d’apprendre que vous n’aimez pas WOLF. Nous aimerions avoir la chance de l’améliorer. Pourriez-vous prendre une minute pour nous dire ce que nous pouvons mieux faire ?','Give Feedback'=>'Donner un avis','No thanks'=>'Non merci','Will never reset published date, and for modified date field  will set current time!'=>'Ne réinitialisera jamais la date de publication ; pour le champ de date de modification, l’heure actuelle sera utilisée !','Product: %s'=>'Produit : %s','Images (%s)'=>'Images (%s)','Post: %s'=>'Article : %s','Array'=>'Tableau','Content[empty]'=>'Contenu [vide]','Not allowed!'=>'Non autorisé !','Posts (%s)'=>'Articles (%s)','Select all'=>'Tout sélectionner','Deselect all'=>'Tout désélectionner','cancel'=>'annuler','save'=>'enregistrer','Set full width'=>'Pleine largeur','Columns profiles'=>'Profils de colonnes','New Post'=>'Nouvel article','Duplicate selected post(s).'=>'Dupliquer les articles sélectionnés.','Delete selected post(s)'=>'Supprimer les articles sélectionnés','Uncheck all selected posts'=>'Décocher tous les articles sélectionnés','Reset filters'=>'Réinitialiser les filtres','select all variations'=>'sélectionner toutes les variations','Scroll right'=>'Défiler vers la droite','Scroll left'=>'Défiler vers la gauche','Detach image of the post'=>'Détacher l’image de l’article','drag and drop'=>'glisser-déposer','Close the panel'=>'Fermer le panneau','No any post type permitted to edit for site editors. Ask please site administrators for details!'=>'Aucun type de contenu n’est autorisé à la modification pour les éditeurs du site. Veuillez contacter les administrateurs du site pour plus de détails !','Your settings have been saved.'=>'Vos réglages ont été enregistrés.','Compatible with WordPress v.%s'=>'Compatible avec WordPress v.%s','MCP server is off. Connect your AI assistant to WOLF: switch it on in the Settings tab - click to read how'=>'Le serveur MCP est désactivé. Pour connecter votre assistant IA à WOLF, activez-le dans l’onglet Réglages – cliquez pour savoir comment','MCP server is on, two-factor connection is off - switching it on in the Settings tab is recommended. Click to read how to connect your AI assistant'=>'Le serveur MCP est activé, la connexion à deux facteurs est désactivée – il est recommandé de l’activer dans l’onglet Réglages. Cliquez pour savoir comment connecter votre assistant IA','MCP server is on, with two-factor connection. Click to read how to connect your AI assistant'=>'Le serveur MCP est activé, avec la connexion à deux facteurs. Cliquez pour savoir comment connecter votre assistant IA','Upgrade'=>'Passer à la version supérieure','ATTENTION! Your version of the WordPress is obsolete. There is no warranty of normal working with the plugin!!'=>'ATTENTION ! Votre version de WordPress est obsolète. Le bon fonctionnement du plugin n’est pas garanti !!','Settings'=>'Réglages','Select some columns in tab "Settings"'=>'Sélectionnez des colonnes dans l’onglet « Réglages »','Actions'=>'Actions','Quick search'=>'Recherche rapide','Quick terms search by its name'=>'Recherche rapide de termes par nom','create new term'=>'créer un nouveau terme','selected only'=>'sélectionnés uniquement','Select all terms'=>'Sélectionner tous les termes','Add Image'=>'Ajouter une image','Replace all posts images by the selected ones'=>'Remplacer toutes les images des articles par celles sélectionnées','Add selected images to the already existed ones'=>'Ajouter les images sélectionnées à celles déjà existantes','Delete selected images from the posts'=>'Retirer les images sélectionnées des articles','Delete selected images from the posts, also delete them from the media library forever'=>'Retirer les images sélectionnées des articles et les supprimer définitivement de la médiathèque','REMEMBER: sequence of data maybe have sense (and maybe not), so be attentive! Do not mix in the same popup window data of array and object data!'=>'RAPPEL : l’ordre des données peut avoir de l’importance (ou non), soyez attentif ! Ne mélangez pas dans la même fenêtre des données de type tableau et objet !','Prepend array key/value'=>'Ajouter au début une clé/valeur de tableau','Prepend object set'=>'Ajouter au début un ensemble d’objet','Append array key/value'=>'Ajouter à la fin une clé/valeur de tableau','Append object set'=>'Ajouter à la fin un ensemble d’objet','key'=>'clé','value'=>'valeur','Note: if horizontal scroll disappeared when it must be visible, click on tab Posts Editor to make it visible'=>'Remarque : si le défilement horizontal a disparu alors qu’il devrait être visible, cliquez sur l’onglet Éditeur d’articles pour le faire réapparaître','Columns settings%1$s, columns enabled %2$s'=>'Réglages des colonnes%1$s, colonnes activées %2$s','Show all columns'=>'Afficher toutes les colonnes','premium version'=>'version premium','visible for the site editor'=>'visible pour l’éditeur du site','cell text or number size'=>'taille du texte ou du nombre dans la cellule','Save all settings'=>'Enregistrer tous les réglages','General settings'=>'Réglages généraux','Site editors post types'=>'Types de contenu des éditeurs du site','What post types can edit site editors in the tab Posts Editor. Use comma, example: post,car,page'=>'Types de contenu que les éditeurs du site peuvent modifier dans l’onglet Éditeur d’articles. Séparez par des virgules, exemple : post,car,page','Separate columns and meta for post types'=>'Colonnes et méta distinctes par type de contenu','Each post type has its own set of columns and meta fields.'=>'Chaque type de contenu a son propre jeu de colonnes et de champs méta.','Show content and excerpt text partly'=>'Afficher une partie du contenu et de l’extrait','Show part of the text in the content and excerpt edit button'=>'Afficher une partie du texte dans le bouton de modification du contenu et de l’extrait','More settings (implicit)'=>'Autres réglages (implicites)','Show description'=>'Afficher la description','Edit'=>'Modifier','Columns profile'=>'Profil de colonnes','Here you can load previously saved columns profile. After pressing on the load button, page reloading will start immediately!'=>'Vous pouvez charger ici un profil de colonnes enregistré précédemment. Après un clic sur le bouton de chargement, la page sera rechargée immédiatement !','Current profile is: %1$s %2$s'=>'Profil actuel : %1$s %2$s','remove current columns profile'=>'supprimer le profil de colonnes actuel','Select profile to load'=>'Sélectionnez le profil à charger','New Profile'=>'Nouveau profil','Here you can type any title and save current columns set and their order. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Saisissez ici un titre pour enregistrer l’ensemble de colonnes actuel et leur ordre. Saisissez un titre puis cliquez sur le bouton Enregistrer OU appuyez sur la touche Entrée de votre clavier !','Create'=>'Créer','New term for [%s]'=>'Nouveau terme pour [%s]','New Term(s)'=>'Nouveau(x) terme(s)','Here you can write title for the new term. Use comma to create some new tags on the same time! New terms with already existed names will not be created!'=>'Saisissez ici le titre du nouveau terme. Utilisez des virgules pour créer plusieurs étiquettes à la fois ! Les nouveaux termes dont le nom existe déjà ne seront pas créés !','Slug(s) of the new term'=>'Identifiant(s) (slug) du nouveau terme','Here you can write slug for the the new term (optionally). Use comma for slug(s) when you create some on the same time terms, or leave slug field empty to create slug(s) automatically'=>'Saisissez ici l’identifiant (slug) du nouveau terme (facultatif). Utilisez des virgules pour les identifiants lorsque vous créez plusieurs termes à la fois, ou laissez le champ vide pour générer les identifiants automatiquement','Parent of the new term(s)'=>'Parent du ou des nouveaux termes','Here you can select parent for the the new term (optionally)'=>'Sélectionnez ici le parent du nouveau terme (facultatif)','UPGRADE TO FULL VERSION'=>'PASSER À LA VERSION COMPLÈTE','WOLF - Posts Bulk Editor Professional'=>'WOLF - Posts Bulk Editor Professional','BEAR - Bulk Editor Professional for WooCommerce'=>'BEAR - Bulk Editor Professional for WooCommerce','BEAR - WooCommerce Bulk Editor Professional'=>'BEAR - WooCommerce Bulk Editor Professional']];